package app.veyra;
import android.content.*;import android.content.pm.*;import android.os.Build;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;
final class AppUpdates {
 static final String RELEASES="https://api.github.com/repos/unidentified24/Velixio/releases?per_page=100";
 static final long MAX_APK=128L*1024*1024;
 static class Release {final String version,url,digest;Release(String v,String u,String d){version=v;url=u;digest=d;}}
 private static boolean checking;
 static synchronized void maybeCheck(android.app.Activity a){android.content.SharedPreferences p=a.getSharedPreferences("update-settings",0);long now=System.currentTimeMillis();if(checking||!p.getBoolean("automatic",true)||now-p.getLong("lastCheck",0)<24*60*60*1000L)return;checking=true;p.edit().putLong("lastCheck",now).apply();new Thread(()->{try{Release r=check(a);if(r!=null)a.runOnUiThread(()->{if(a.isFinishing()||a.isDestroyed()||r.version.equals(p.getString("noticed","")))return;p.edit().putString("noticed",r.version).apply();ActionSheet.show(a,"Velixio "+r.version+" is available",new String[]{"View update","Later"},i->{if(i==0)a.startActivity(new Intent(a,UpdatesActivity.class));});});}catch(Exception ignored){p.edit().putLong("lastCheck",System.currentTimeMillis()-23*60*60*1000L).apply();}finally{synchronized(AppUpdates.class){checking=false;}}},"update-check").start();}
 static int compare(String a,String b){int[] x=version(a),y=version(b);for(int i=0;i<x.length;i++){int c=Integer.compare(x[i],y[i]);if(c!=0)return c;}return 0;}
 static String normalized(String text){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?i)(?<![0-9])v?([0-9]{1,4}\\.[0-9]{1,4}\\.[0-9]{1,4}(?:-(?:rc)?[0-9]{1,4})?)(?![0-9])").matcher(text);return m.find()?m.group(1).toLowerCase(Locale.ROOT):"";}
 private static int[] version(String text){String n=normalized(text);if(n.isEmpty())return new int[]{-1,0,0,0,0};String[] parts=n.split("-",2),core=parts[0].split("\\.");int stage=1,revision=0;if(parts.length>1){boolean rc=parts[1].startsWith("rc");stage=rc?0:1;revision=Integer.parseInt(rc?parts[1].substring(2):parts[1]);}return new int[]{Integer.parseInt(core[0]),Integer.parseInt(core[1]),Integer.parseInt(core[2]),stage,revision};}
 static Release select(JSONArray releases,String installed)throws Exception{Release selected=null;for(int i=0;i<releases.length();i++){JSONObject r=releases.getJSONObject(i);String tag=normalized(r.optString("tag_name"));if(tag.isEmpty())tag=normalized(r.optString("name"));if(r.optBoolean("draft")||(!installed.contains("-rc")&&(r.optBoolean("prerelease")||tag.contains("-rc")))||compare(tag,installed)<=0||(selected!=null&&compare(tag,selected.version)<=0))continue;JSONArray assets=r.optJSONArray("assets");if(assets==null)continue;for(int n=0;n<assets.length();n++){JSONObject asset=assets.getJSONObject(n);String url=asset.optString("browser_download_url"),hash=asset.optString("digest");if(asset.optString("name").endsWith(".apk")&&url.startsWith("https://github.com/unidentified24/Velixio/releases/download/")&&hash.matches("sha256:[0-9a-fA-F]{64}")&&asset.optLong("size")>0&&asset.optLong("size")<=MAX_APK){selected=new Release(tag,url,hash.substring(7));break;}}}return selected;}
 static HttpURLConnection connection(String address)throws Exception{for(int redirects=0;redirects<6;redirects++){URI uri=URI.create(address);String host=uri.getHost();if(!"https".equals(uri.getScheme())||uri.getRawUserInfo()!=null||!("api.github.com".equals(host)||"github.com".equals(host)||"release-assets.githubusercontent.com".equals(host)||"objects.githubusercontent.com".equals(host)))throw new IOException("Unexpected update host");HttpURLConnection c=(HttpURLConnection)uri.toURL().openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","Velixio-Updater");int code=c.getResponseCode();if(code==200)return c;if(code>=300&&code<400){String next=c.getHeaderField("Location");c.disconnect();address=uri.resolve(next).toString();continue;}c.disconnect();throw new IOException("Release service unavailable ("+code+")");}throw new IOException("Too many redirects");}
 static Release check(Context c)throws Exception{pruneUpdates(c);HttpURLConnection conn=connection(RELEASES);try(InputStream in=conn.getInputStream()){String json=app.veyra.data.CatalogBackend.read(in,2*1024*1024);String installed=c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName;return select(new JSONArray(json),installed);}finally{conn.disconnect();}}
 static void pruneUpdates(Context c){File dir=new File(c.getCacheDir(),"updates");File[] files=dir.listFiles();if(files==null)return;long cutoff=System.currentTimeMillis()-24*60*60*1000L;for(File f:files)if(f.isFile()&&f.getName().endsWith(".apk")&&f.lastModified()<cutoff)f.delete();}
 interface Progress{void update(long bytes,long total);}
 static File download(Context c,Release r,Progress progress)throws Exception{File dir=new File(c.getCacheDir(),"updates");dir.mkdirs();File file=new File(dir,UUID.randomUUID()+".apk");HttpURLConnection conn=null;boolean verified=false;try{conn=connection(r.url);long total=conn.getContentLengthLong();if(total>MAX_APK)throw new IOException("Update too large");MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=conn.getInputStream();OutputStream out=new FileOutputStream(file)){byte[] bytes=new byte[32768];long count=0,last=0;int n;while((n=in.read(bytes))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();count+=n;if(count>MAX_APK)throw new IOException("Update too large");out.write(bytes,0,n);digest.update(bytes,0,n);long now=System.currentTimeMillis();if(now-last>250){progress.update(count,total);last=now;}}}if(!hex(digest.digest()).equalsIgnoreCase(r.digest))throw new SecurityException("Update checksum mismatch");verify(c,file);verified=true;return file;}finally{if(conn!=null)conn.disconnect();if(!verified)file.delete();}}
 static String hex(byte[] data){StringBuilder b=new StringBuilder();for(byte v:data)b.append(String.format(Locale.ROOT,"%02x",v&255));return b.toString();}
 static void verify(Context c,File file)throws Exception{int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo next=c.getPackageManager().getPackageArchiveInfo(file.getPath(),flags),current=c.getPackageManager().getPackageInfo(c.getPackageName(),flags);if(next==null||!c.getPackageName().equals(next.packageName)||(Build.VERSION.SDK_INT>=28?next.getLongVersionCode()<=current.getLongVersionCode():next.versionCode<=current.versionCode))throw new SecurityException("Not a newer Velixio package");android.content.pm.Signature[] ns=Build.VERSION.SDK_INT>=28?next.signingInfo.getApkContentsSigners():next.signatures,cs=Build.VERSION.SDK_INT>=28?current.signingInfo.getApkContentsSigners():current.signatures;if(ns==null||cs==null||ns.length!=cs.length||ns.length==0)throw new SecurityException("Signing identity mismatch");Set<String> trusted=new HashSet<>();for(android.content.pm.Signature s:cs)trusted.add(hex(s.toByteArray()));for(android.content.pm.Signature s:ns)if(!trusted.contains(hex(s.toByteArray())))throw new SecurityException("Signing identity mismatch");}
}
